sp_widget.script:
(function() {
    data.message = "";
    data.number = "";

    var type = $sp.getParameter('type'); // from URL
    var recordId = $sp.getParameter('record_id');

    var tableMap = {
			  'employee_creation':'x_594089_employe_0_hr_employee',
				'employee_review':'x_594089_employe_0_performance_review',
				'manager_review':'x_594089_employe_0_performance_review',
        'leave': 'x_594089_employe_0_leave_request',
        'grievance': 'x_594089_employe_0_grievance',
        'training': 'x_594089_employe_0_training_request',
				'exit_request':'x_594089_employe_0_exit_request'
    	};
			console.log(tableMap[type]);
			console.log(recordId);
			if (recordId && tableMap[type]) {
					var gr = new GlideRecord(tableMap[type]);
					if (gr.get(recordId)) {
							data.number = gr.number.toString();
					}
			}

    var messages = {
        'leave': "Your leave request has been submitted successfully!",
        'grievance': "Your grievance has been submitted. We will review it soon!",
        'performance': "Your performance review is submitted!",
        'training': "Your training request is submitted!",
				'employee_creation':'Employee record successfully created. Kindly mail the user credentials for further process.',
				'employee_review':'Your review has been successfully submitted. Kindly wait for your manager to fill as well.',
				'manager_review':'You have successfully completed the review.',
				'exit_request':'Exit request successfully submitted. Kindly wait for the onboarding tasks.'
    };

    data.message = messages[type] || "Your request has been submitted!";
})();
